output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper who starts a trip must first take the entrance cart before collecting items or exiting.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_cell": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_entrance_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_cell",
              "PICKUP_CART"
            ]
          },
          "post": "has_entrance_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "return_taken_cart",
    "text": "Any cart taken from the entrance must eventually be returned to the cart-return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "entrance_cart_cell": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "cart_return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_cell",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_entrance_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "It is forbidden to put down a cart anywhere except the designated cart-return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "leave_cart_at_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper may exit only when the cart is already stationed at the cart-return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "ready_to_exit_on_foot": {
          "and": [
            "cart_parked_at_return_bay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "ready_to_exit_on_foot"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_exit_zone",
    "text": "Carts are forbidden in the pedestrian exit zone near the store exit.",
    "abstraction": {
      "state_properties": {
        "pedestrian_exit_zone": {
          "or": [
            "at(8,5)",
            "at(9,5)",
            "at(9,4)",
            "at(8,4)"
          ]
        },
        "pushing_cart_in_exit_zone": {
          "and": [
            "hasCart",
            "pedestrian_exit_zone"
          ]
        }
      },
      "events": {
        "enter_exit_zone_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "pedestrian_exit_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushing_cart_in_exit_zone"
    }
  },
  {
    "id": "no_cart_lower_middle_aisle",
    "text": "The lower middle aisle is a cart-free walking corridor, so shoppers may pass there only after leaving the cart behind.",
    "abstraction": {
      "state_properties": {
        "lower_middle_corridor": {
          "or": [
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)"
          ]
        },
        "cart_in_lower_middle_corridor": {
          "and": [
            "hasCart",
            "lower_middle_corridor"
          ]
        }
      },
      "events": {
        "walk_lower_middle_without_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "lower_middle_corridor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_lower_middle_corridor"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Shelf items must be collected into a cart rather than carried by hand.",
    "abstraction": {
      "state_properties": {
        "shopping_by_hand": "handFull",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "take_item_without_cart": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "take_item_into_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "shopping_by_hand",
          "take_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "no_east_from_far_shelf_with_cart",
    "text": "After reaching the far-right shelf area with a cart, shoppers must not continue east with the cart and should turn back toward the return bay.",
    "abstraction": {
      "state_properties": {
        "far_right_shelf_area": {
          "or": [
            "at(6,4)",
            "at(6,2)"
          ]
        },
        "pushing_cart_at_far_right_shelf": {
          "and": [
            "hasCart",
            "far_right_shelf_area"
          ]
        }
      },
      "events": {
        "interact_at_far_right_shelf_with_cart": {
          "pre": {
            "and": [
              "pushing_cart_at_far_right_shelf",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "push_cart_east_from_far_right_shelf": {
          "pre": {
            "and": [
              "pushing_cart_at_far_right_shelf",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_from_far_right_shelf"
    }
  }
]
